const userInput = '<img src=x onerror="alert(1)">'

// ❌ innerHTML — HTML로 파싱해서 삽입
element.innerHTML = userInput
// → img 태그가 실제로 생성됨
// → onerror 이벤트 실행됨
// → XSS 발생

// ✅ textContent — 문자열 그대로 삽입
element.textContent = userInput
// → '<img src=x onerror="alert(1)">' 라는 텍스트가 그냥 보임
// → HTML로 해석 안 됨
// → XSS 없음

